  (sid, eng_id, 'mcq', 'In the poem "The Song of India", the poet speaks of "Epics in Stone", which refers to:', '[{"key": "A", "value": "The modern industrial steel mills", "correct": false}, {"key": "B", "value": "The ancient temples and architectural marvels carved in rock", "correct": true}, {"key": "C", "value": "The books written by freedom fighters", "correct": false}, {"key": "D", "value": "The stories of common people working in fields", "correct": false}]', 'B', 1, 'easy', '["The Song of India"]', '["comprehension"]', true),
